import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry input validation', () => {
  it('compiles a static schema once and reuses it across ten executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'echo', description: 'Echo text', inputSchema: {type: 'object', properties: {text: {type: 'string'}}}},
      async input => String(input.text)
    );

    for (let index = 0; index < 10; index += 1) {
      await registry.execute('echo', {text: 'hello'});
    }

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('rejects input missing a required property and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register({name: 'weather', description: 'Weather', inputSchema: {required: ['location']}}, execute);

    expect({result: (await registry.execute('weather', {})).result, calls: execute.mock.calls.length}).toMatchObject({
      result: expect.stringMatching(/location.*required/i),
      calls: 0,
    });
  });

  it('names the tool and preserves the schema compilation error as its cause', () => {
    const registry = new ToolRegistry();

    try {
      registry.register(
        {name: 'broken-weather', description: 'Weather', inputSchema: {type: 'not-a-json-schema-type'}},
        async () => 'sunny'
      );
      throw new Error('Expected registration to reject the invalid schema');
    } catch (error) {
      expect(error).toMatchObject({
        message: expect.stringContaining('broken-weather'),
        cause: expect.any(Error),
      });
    }
  });

  it('formats a slash in a required property name as a JSON Pointer path', async () => {
    const registry = new ToolRegistry();
    registry.register({name: 'slash', description: 'Slash', inputSchema: {required: ['a/b']}}, async () => 'ok');

    expect((await registry.execute('slash', {})).result).toBe('Invalid input for tool slash: /a~1b is required');
  });

  it('uses JSON Pointer escaping for tildes and slashes in required property paths', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'ok');
    registry.register({name: 'escaped', description: 'Escaped', inputSchema: {required: ['a~/b']}}, execute);

    expect({result: (await registry.execute('escaped', {})).result, calls: execute.mock.calls.length}).toEqual({
      result: 'Invalid input for tool escaped: /a~0~1b is required',
      calls: 0,
    });
  });

  it('escapes special characters in required property paths', async () => {
    const registry = new ToolRegistry();
    registry.register({name: 'special', description: 'Special', inputSchema: {required: ['a/b']}}, async () => 'ok');

    expect((await registry.execute('special', {})).result).toContain('/a~1b is required');
  });

  it('formats Ajv quoted missing-property paths as JSON Pointers', async () => {
    const registry = new ToolRegistry();
    registry.register({name: 'quoted', description: 'Quoted', inputSchema: {required: ['a/b']}}, async () => 'ok');

    expect((await registry.execute('quoted', {})).result).toBe('Invalid input for tool quoted: /a~1b is required');
  });
});
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv, {type ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

function formatValidationErrors(errors: NonNullable<ValidateFunction['errors']>): string {
  return errors
    .map(error => {
      const params = error.params as Record<string, unknown>;
      const missingProperty = String(params.missingProperty ?? '')
        .replace(/^\['([\s\S]*)'\]$/, '$1')
        .replace(/^'([\s\S]*)'$/, '$1');
      const path =
        `${'instancePath' in error ? error.instancePath : ''}${error.keyword === 'required' ? `/${missingProperty.replace(/~/g, '~0').replace(/\//g, '~1')}` : ''}` ||
        '/';
      return `${path} ${error.keyword === 'required' ? 'is required' : `must be ${String(params.type ?? error.keyword)}`}`;
    })
    .join('; ');
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(
          `Invalid inputSchema for tool ${resolved.name}: ${error instanceof Error ? error.message : String(error)}`,
          {cause: error}
        );
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for rejection and unknown-tool behavior. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator = tool.validator;
    validator ??= this.validators.get(definition.inputSchema);
    if (!validator) {
      validator = this.ajv.compile(definition.inputSchema);
      this.validators.set(definition.inputSchema, validator);
    }
    if (!validator(input)) {
      return {result: `Invalid input for tool ${name}: ${formatValidationErrors(validator.errors ?? [])}`};
    }

    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- Required-property rejection paths use JSON Pointer escaping for `~` and `/`, so unusual property names remain unambiguous ([validated by: formats a slash in a required property name as a JSON Pointer path](../../src/orchestration/tools/registry.test.ts#L50), [validated by: uses JSON Pointer escaping for tildes and slashes in required property paths](../../src/orchestration/tools/registry.test.ts#L57), [validated by formats Ajv quoted missing-property paths as JSON Pointers](../../src/orchestration/tools/registry.test.ts#L75)).

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: escapes special characters in required property paths](../../src/orchestration/tools/registry.test.ts#L68), [validated by: rejects input missing a required property and never calls the executor](../../src/orchestration/tools/registry.test.ts#L22), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- The registration error for an invalid static schema preserves the validator's compilation error as its cause ([validated by: names the tool and preserves the schema compilation error as its cause](../../src/orchestration/tools/registry.test.ts#L33)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- Registering a static tool compiles its schema once, and ten executions reuse that compiled validator ([validated by: compiles a static schema once and reuses it across ten executions](../../src/orchestration/tools/registry.test.ts#L6)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
